.orbital-glass {
  background: rgba(8, 13, 27, 0.75);
  backdrop-filter: blur(20px) saturate(190%);
  -webkit-backdrop-filter: blur(20px) saturate(190%);
  border: 1px solid rgba(86, 229, 255, 0.16);
  box-shadow: 0 8px 32px 0 rgba(0, 0, 0, 0.45);
  position: relative;
  overflow: hidden;
}

.orbital-glass::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 1px;
  background: linear-gradient(90deg, transparent, rgba(245, 250, 255, 0.35), transparent);
  pointer-events: none;
}

.glow-button {
  background: linear-gradient(135deg, #56e5ff 0%, #368bff 100%);
  color: #03050b;
  font-weight: 700;
  padding: 0.625rem 1.25rem;
  border-radius: 0.75rem;
  transition: all 0.25s cubic-bezier(0.16, 1, 0.3, 1);
  box-shadow: 0 0 15px rgba(86, 229, 255, 0.25);
}

.glow-button:hover {
  filter: brightness(1.1);
  transform: translateY(-2px);
  box-shadow: 0 0 25px rgba(86, 229, 255, 0.45);
}

.glow-button:active {
  transform: translateY(0);
}
